import{_ as a,o as s,c as n,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"etcd Key Schema","description":"","frontmatter":{},"headers":[],"relativePath":"reference/etcd-schema.md","filePath":"reference/etcd-schema.md"}'),i={name:"reference/etcd-schema.md"};function p(l,e,o,c,r,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="etcd-key-schema" tabindex="-1">etcd Key Schema <a class="header-anchor" href="#etcd-key-schema" aria-label="Permalink to &quot;etcd Key Schema&quot;">​</a></h1><p>Every key in the CCattler fact store lives under a top-level prefix that separates desired state from observed state. This boundary is the foundation of the security model and the reconciliation loop.</p><h2 id="key-hierarchy" tabindex="-1">Key hierarchy <a class="header-anchor" href="#key-hierarchy" aria-label="Permalink to &quot;Key hierarchy&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ccattler/</span></span>
<span class="line"><span>├── desired/                        # what the world should look like</span></span>
<span class="line"><span>│   ├── service/{name}              # service definition</span></span>
<span class="line"><span>│   ├── service/{name}/image</span></span>
<span class="line"><span>│   ├── service/{name}/instances</span></span>
<span class="line"><span>│   ├── service/{name}/expose/{port}</span></span>
<span class="line"><span>│   ├── service/{name}/resources/cpu</span></span>
<span class="line"><span>│   ├── service/{name}/resources/memory</span></span>
<span class="line"><span>│   ├── service/{name}/health/method</span></span>
<span class="line"><span>│   ├── service/{name}/health/path</span></span>
<span class="line"><span>│   ├── service/{name}/health/interval</span></span>
<span class="line"><span>│   ├── service/{name}/autoscale/metric</span></span>
<span class="line"><span>│   ├── service/{name}/autoscale/threshold</span></span>
<span class="line"><span>│   ├── service/{name}/autoscale/min</span></span>
<span class="line"><span>│   ├── service/{name}/autoscale/max</span></span>
<span class="line"><span>│   ├── service/{name}/placement/architecture</span></span>
<span class="line"><span>│   ├── service/{name}/placement/zone</span></span>
<span class="line"><span>│   ├── service/{name}/update/max_unavailable</span></span>
<span class="line"><span>│   ├── service/{name}/update/max_extra</span></span>
<span class="line"><span>│   ├── volume/{name}</span></span>
<span class="line"><span>│   ├── volume/{name}/size</span></span>
<span class="line"><span>│   ├── volume/{name}/persistent</span></span>
<span class="line"><span>│   └── volume/{name}/access_mode</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── effective/                      # derived desired state</span></span>
<span class="line"><span>│   └── service/{name}/instances    # target after user + autoscaler + policy</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── observed/                       # what the world actually looks like</span></span>
<span class="line"><span>│   ├── node/{node-id}</span></span>
<span class="line"><span>│   ├── node/{node-id}/state        # alive | unreachable | draining</span></span>
<span class="line"><span>│   ├── node/{node-id}/capacity/cpu</span></span>
<span class="line"><span>│   ├── node/{node-id}/capacity/memory</span></span>
<span class="line"><span>│   ├── node/{node-id}/available/cpu</span></span>
<span class="line"><span>│   ├── node/{node-id}/available/memory</span></span>
<span class="line"><span>│   ├── node/{node-id}/architecture</span></span>
<span class="line"><span>│   ├── node/{node-id}/zone</span></span>
<span class="line"><span>│   ├── instance/{instance-id}</span></span>
<span class="line"><span>│   ├── instance/{instance-id}/service</span></span>
<span class="line"><span>│   ├── instance/{instance-id}/node</span></span>
<span class="line"><span>│   ├── instance/{instance-id}/state  # pending | running | failed | stopped</span></span>
<span class="line"><span>│   ├── instance/{instance-id}/image</span></span>
<span class="line"><span>│   ├── instance/{instance-id}/ip</span></span>
<span class="line"><span>│   ├── instance/{instance-id}/health</span></span>
<span class="line"><span>│   ├── instance/{instance-id}/started_at</span></span>
<span class="line"><span>│   ├── volume/{name}/attached_node</span></span>
<span class="line"><span>│   └── volume/{name}/state           # attached | detached | error</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── placement/                      # scheduling decisions</span></span>
<span class="line"><span>│   └── instance/{instance-id}      # value = node-id</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── endpoint/                       # derived network state</span></span>
<span class="line"><span>│   └── service/{name}/{instance-id}  # value = {ip, port}</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── intent/                         # multi-writer resolution</span></span>
<span class="line"><span>│   ├── user/service/{name}/instances</span></span>
<span class="line"><span>│   ├── autoscaler/service/{name}/instances</span></span>
<span class="line"><span>│   └── policy/service/{name}/instances</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── lease/                          # TTL leases for liveness</span></span>
<span class="line"><span>│   └── node/{node-id}</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── event/                          # append-only history</span></span>
<span class="line"><span>│   └── {timestamp}-{sequence}</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── auth/                           # permissions</span></span>
<span class="line"><span>│   └── {principal}/rules</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── schema/                         # plugin fact type registrations</span></span>
<span class="line"><span>    └── {fact-type}</span></span></code></pre></div><h2 id="key-design-decisions" tabindex="-1">Key design decisions <a class="header-anchor" href="#key-design-decisions" aria-label="Permalink to &quot;Key design decisions&quot;">​</a></h2><h3 id="desired-observed-separation" tabindex="-1">Desired / observed separation <a class="header-anchor" href="#desired-observed-separation" aria-label="Permalink to &quot;Desired / observed separation&quot;">​</a></h3><p>The most important structural choice. Different actors with different trust levels write to each tree:</p><table tabindex="0"><thead><tr><th>Tree</th><th>Writers</th><th>Trust level</th></tr></thead><tbody><tr><td><code>desired/</code></td><td>Users, policy controllers, autoscaler</td><td>Trusted — authenticated, authorized</td></tr><tr><td><code>observed/</code></td><td>Node agents</td><td>Partially trusted — can only report reality</td></tr><tr><td><code>placement/</code></td><td>Scheduler</td><td>Trusted — control plane component</td></tr><tr><td><code>endpoint/</code></td><td>Network controller</td><td>Trusted — derived from observed</td></tr><tr><td><code>effective/</code></td><td>Intent resolver</td><td>Trusted — computed from intent layers</td></tr></tbody></table><p>A compromised node agent can write to <code>observed/</code> but never to <code>desired/</code>.</p><h3 id="instance-identity" tabindex="-1">Instance identity <a class="header-anchor" href="#instance-identity" aria-label="Permalink to &quot;Instance identity&quot;">​</a></h3><p>Instances get short random IDs (e.g., <code>a8f31</code>), not sequential numbers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>observed/instance/a8f31/service  → &quot;web&quot;</span></span>
<span class="line"><span>observed/instance/a8f31/node     → &quot;node-2&quot;</span></span>
<span class="line"><span>observed/instance/a8f31/state    → &quot;running&quot;</span></span></code></pre></div><h3 id="flat-facts-not-nested-objects" tabindex="-1">Flat facts, not nested objects <a class="header-anchor" href="#flat-facts-not-nested-objects" aria-label="Permalink to &quot;Flat facts, not nested objects&quot;">​</a></h3><p>Each fact is its own key. This enables fine-grained watches, atomic field updates, and prefix scans.</p><h3 id="revisions-and-optimistic-concurrency" tabindex="-1">Revisions and optimistic concurrency <a class="header-anchor" href="#revisions-and-optimistic-concurrency" aria-label="Permalink to &quot;Revisions and optimistic concurrency&quot;">​</a></h3><p>Every key mutation increments the global revision. Transactions use revision-based compare-and-swap to prevent conflicts.</p><h3 id="leases-for-node-liveness" tabindex="-1">Leases for node liveness <a class="header-anchor" href="#leases-for-node-liveness" aria-label="Permalink to &quot;Leases for node liveness&quot;">​</a></h3><p>Each node agent creates a lease with a TTL (30s) and continuously refreshes it. If the agent crashes, the lease expires and the failure controller detects it.</p><h2 id="worked-example-service-lifecycle" tabindex="-1">Worked example: service lifecycle <a class="header-anchor" href="#worked-example-service-lifecycle" aria-label="Permalink to &quot;Worked example: service lifecycle&quot;">​</a></h2><h3 id="_1-user-applies-config" tabindex="-1">1. User applies config <a class="header-anchor" href="#_1-user-applies-config" aria-label="Permalink to &quot;1. User applies config&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUT desired/service/web              → {}</span></span>
<span class="line"><span>PUT desired/service/web/image        → &quot;nginx:1.28&quot;</span></span>
<span class="line"><span>PUT desired/service/web/instances    → 3</span></span>
<span class="line"><span>PUT desired/service/web/expose/8080  → {}</span></span>
<span class="line"><span>PUT intent/user/service/web/instances → 3</span></span></code></pre></div><h3 id="_2-intent-resolver-computes-effective-state" tabindex="-1">2. Intent resolver computes effective state <a class="header-anchor" href="#_2-intent-resolver-computes-effective-state" aria-label="Permalink to &quot;2. Intent resolver computes effective state&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUT effective/service/web/instances → 3</span></span></code></pre></div><h3 id="_3-instance-controller-desired-3-actual-0" tabindex="-1">3. Instance controller: desired=3, actual=0 <a class="header-anchor" href="#_3-instance-controller-desired-3-actual-0" aria-label="Permalink to &quot;3. Instance controller: desired=3, actual=0&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUT observed/instance/a8f31/service → &quot;web&quot;</span></span>
<span class="line"><span>PUT observed/instance/a8f31/state   → &quot;pending&quot;</span></span>
<span class="line"><span>PUT observed/instance/b72c9/service → &quot;web&quot;</span></span>
<span class="line"><span>PUT observed/instance/b72c9/state   → &quot;pending&quot;</span></span>
<span class="line"><span>PUT observed/instance/c913d/service → &quot;web&quot;</span></span>
<span class="line"><span>PUT observed/instance/c913d/state   → &quot;pending&quot;</span></span></code></pre></div><h3 id="_4-scheduler-places-instances" tabindex="-1">4. Scheduler places instances <a class="header-anchor" href="#_4-scheduler-places-instances" aria-label="Permalink to &quot;4. Scheduler places instances&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUT placement/instance/a8f31 → &quot;node-1&quot;</span></span>
<span class="line"><span>PUT placement/instance/b72c9 → &quot;node-2&quot;</span></span>
<span class="line"><span>PUT placement/instance/c913d → &quot;node-3&quot;</span></span></code></pre></div><h3 id="_5-node-agents-start-containers-and-report" tabindex="-1">5. Node agents start containers and report <a class="header-anchor" href="#_5-node-agents-start-containers-and-report" aria-label="Permalink to &quot;5. Node agents start containers and report&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUT observed/instance/a8f31/node       → &quot;node-1&quot;</span></span>
<span class="line"><span>PUT observed/instance/a8f31/state      → &quot;running&quot;</span></span>
<span class="line"><span>PUT observed/instance/a8f31/ip         → &quot;10.1.0.5&quot;</span></span>
<span class="line"><span>PUT observed/instance/a8f31/health     → &quot;healthy&quot;</span></span></code></pre></div><h3 id="_6-network-controller-derives-endpoints" tabindex="-1">6. Network controller derives endpoints <a class="header-anchor" href="#_6-network-controller-derives-endpoints" aria-label="Permalink to &quot;6. Network controller derives endpoints&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUT endpoint/service/web/a8f31 → {&quot;ip&quot;: &quot;10.1.0.5&quot;, &quot;port&quot;: 8080}</span></span>
<span class="line"><span>PUT endpoint/service/web/b72c9 → {&quot;ip&quot;: &quot;10.1.0.9&quot;, &quot;port&quot;: 8080}</span></span>
<span class="line"><span>PUT endpoint/service/web/c913d → {&quot;ip&quot;: &quot;10.1.0.12&quot;, &quot;port&quot;: 8080}</span></span></code></pre></div><h2 id="worked-example-node-failure" tabindex="-1">Worked example: node failure <a class="header-anchor" href="#worked-example-node-failure" aria-label="Permalink to &quot;Worked example: node failure&quot;">​</a></h2><h3 id="node-2-crashes" tabindex="-1">Node-2 crashes <a class="header-anchor" href="#node-2-crashes" aria-label="Permalink to &quot;Node-2 crashes&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lease lease/node/node-2 expires (no refresh for 30s)</span></span></code></pre></div><h3 id="failure-controller-detects" tabindex="-1">Failure controller detects <a class="header-anchor" href="#failure-controller-detects" aria-label="Permalink to &quot;Failure controller detects&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUT observed/node/node-2/state → &quot;unreachable&quot;</span></span></code></pre></div><h3 id="instance-controller-creates-replacement" tabindex="-1">Instance controller creates replacement <a class="header-anchor" href="#instance-controller-creates-replacement" aria-label="Permalink to &quot;Instance controller creates replacement&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUT observed/instance/d41ab/service → &quot;web&quot;</span></span>
<span class="line"><span>PUT observed/instance/d41ab/state   → &quot;pending&quot;</span></span></code></pre></div><h3 id="scheduler-places-replacement" tabindex="-1">Scheduler places replacement <a class="header-anchor" href="#scheduler-places-replacement" aria-label="Permalink to &quot;Scheduler places replacement&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUT placement/instance/d41ab → &quot;node-3&quot;</span></span></code></pre></div><h3 id="network-controller-updates-endpoints" tabindex="-1">Network controller updates endpoints <a class="header-anchor" href="#network-controller-updates-endpoints" aria-label="Permalink to &quot;Network controller updates endpoints&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DELETE endpoint/service/web/b72c9</span></span>
<span class="line"><span>PUT    endpoint/service/web/d41ab → {&quot;ip&quot;: &quot;10.1.0.17&quot;, &quot;port&quot;: 8080}</span></span></code></pre></div><p>System converged. No component called another. All communication through state.</p><h2 id="network-partition-behavior" tabindex="-1">Network partition behavior <a class="header-anchor" href="#network-partition-behavior" aria-label="Permalink to &quot;Network partition behavior&quot;">​</a></h2><h3 id="nodes-can-t-reach-etcd" tabindex="-1">Nodes can&#39;t reach etcd <a class="header-anchor" href="#nodes-can-t-reach-etcd" aria-label="Permalink to &quot;Nodes can&#39;t reach etcd&quot;">​</a></h3><ul><li>Nodes keep running workloads (cached desired state)</li><li>Leases expire → control plane marks nodes unreachable</li><li>Control plane may create replacement instances on reachable nodes</li><li>When partition heals: agents re-report, duplicates detected and reconciled</li></ul><h3 id="etcd-loses-quorum" tabindex="-1">etcd loses quorum <a class="header-anchor" href="#etcd-loses-quorum" aria-label="Permalink to &quot;etcd loses quorum&quot;">​</a></h3><ul><li>etcd rejects all writes (safety)</li><li>Controllers stall (no watches fire, no transactions succeed)</li><li>Node agents keep running containers (last known state)</li><li>When quorum restores: watches resume, controllers reconcile, system converges</li></ul><p><strong>Design invariant:</strong> temporary control-plane failure must never automatically destroy data-plane availability.</p>`,49)])])}const v=a(i,[["render",p]]);export{u as __pageData,v as default};
